WITH remaining_keys AS (SELECT order_id, product_id FROM order_items EXCEPT SELECT order_id, product_id FROM order_items WHERE quantity < 3), kept_rows AS (SELECT s.* FROM order_items s INNER JOIN remaining_keys k ON s.order_id = k.order_id AND s.product_id = k.product_id) SELECT s.id, s.order_id, s.unit_price, (SELECT MIN(o2.quantity) FROM order_items o2 WHERE o2.order_id = s.order_id) AS min_order_item_quantity FROM kept_rows s ORDER BY unit_price, min_order_item_quantity;
